def solution() -> int:
    # Compute LCS length for the given strings
    S = 'es'
    T = 'bc'

    m, n = len(S), len(T)
    # DP table with (m+1) x (n+1) initialized to 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if S[i - 1] == T[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return int(dp[m][n])

if __name__ == '__main__':
