def solution() -> int:
    import itertools
    # Cost matrix
    C = [[9, 5], [17, 8]]
    n = len(C)
    min_cost = float('inf')
    # Try all assignments (permutations of tasks)
    for perm in itertools.permutations(range(n)):
        cost = sum(C[i][perm[i]] for i in range(n))
        if cost < min_cost:
            min_cost = cost
    return int(min_cost)

