def solution() -> int:
    # Partition problem: split weights into two groups minimizing absolute difference
    weights = [25, 28, 1, 29]
    total = sum(weights)

    # Dynamic programming subset-sum boolean table (bitset approach)
    # dp[s] == True if a subset sum 's' is achievable
    dp = [False] * (total + 1)
    dp[0] = True
    for w in weights:
        # iterate backwards to avoid reuse of the same item
        for s in range(total, w - 1, -1):
            if dp[s - w]:
                dp[s] = True

    # Find subset sum s that minimizes |total - 2*s|
    best_diff = total  # initialize with a large value
    for s in range(total + 1):
        if dp[s]:
            diff = abs(total - 2 * s)
            if diff < best_diff:
                best_diff = diff

    return int(best_diff)

