def solution() -> int:
    # Partition problem: find minimum absolute difference between two subset sums
    weights = [23, 15, 15, 30]
    total = sum(weights)
    half = total // 2

    # dp[s] will be True if a subset sum s is achievable
    dp = [False] * (half + 1)
    dp[0] = True

    for w in weights:
        # iterate backwards to avoid reusing the same item
        for s in range(half, w - 1, -1):
            if dp[s - w]:
                dp[s] = True

    # find the achievable subset sum closest to half
    for s in range(half, -1, -1):
        if dp[s]:
            min_diff = total - 2 * s
            return int(min_diff)

    # fallback (should not be reached)
    return int(total)

