def solution() -> Tuple[List[int], int]:
    # Define directed weighted graph as adjacency list: node -> list of (neighbor, weight)
    graph = {
        0: [(3, 3)],
        1: [],
        2: [(0, 2)],
        3: [(4, 2), (1, 7)],
        4: [(0, 2), (1, 2)]
    }

    start = 0
    target = 4

    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0
    pq = [(0, start)]  # (distance, node)

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == target:
            break
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))

    if dist[target] == float('inf'):
        return ([], -1)

    # Reconstruct path
    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()

    return (path, int(dist[target]))
