from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # Directed edges (u -> v, weight)
    edges = [
        (2, 0, 7),
        (3, 0, 7),
        (3, 2, 5),
        (1, 3, 2),
        (2, 1, 6),
        (4, 1, 6),
    ]

    # Build adjacency list for directed graph
    graph = {}
    nodes = set()
    for u, v, w in edges:
        graph.setdefault(u, []).append((v, w))
        nodes.add(u); nodes.add(v)

    start = 0
    target = 4

    # Dijkstra's algorithm
    dist = {n: float('inf') for n in nodes}
    prev = {}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == target:
            break
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    # If target unreachable, return empty path and -1
    if dist.get(target, float('inf')) == float('inf'):
        return ([], -1)

    # Reconstruct path
    path = []
    node = target
    while node != start:
        path.append(node)
        node = prev[node]
    path.append(start)
    path.reverse()

    return (path, int(dist[target]))

