from typing import Dict

def solution() -> Dict[int, str]:
    # Define edges of the graph
    edges = [(1, 3), (1, 4), (2, 3), (3, 6), (4, 5)]

    # Build adjacency
    adj = {i: set() for i in range(1, 7)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Greedy/BFS coloring using two colors 'A' and 'B'
    colors: Dict[int, str] = {}
    for node in range(1, 7):
        if node in colors:
            continue
        # assign default color 'A'
        colors[node] = 'A'
        stack = [node]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v in colors:
                    # If conflict (same color) flip neighbor (should not be needed for this graph)
                    if colors[v] == colors[u]:
                        colors[v] = 'A' if colors[u] == 'B' else 'B'
                    continue
                # assign opposite color to neighbor
                colors[v] = 'A' if colors[u] == 'B' else 'B'
                stack.append(v)

    return colors

