def solution() -> dict:
    Find a valid 3-coloring for the given graph and return a mapping
    from vertex (int) to color (str).

    from typing import Dict, List, Tuple

    # vertices 1..6
    vertices: List[int] = [1, 2, 3, 4, 5, 6]
    # edges as given (undirected)
    edges: List[Tuple[int, int]] = [
        (1, 6),
        (2, 4), (2, 5), (2, 6),
        (3, 5), (3, 6),
        (4, 6),
    ]
    # adjacency map for quick checks
    adj = {v: set() for v in vertices}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors: List[str] = ["A", "B", "C"]

    assignment: Dict[int, str] = {}

    def valid(v: int, c: str) -> bool:
        # check neighbors of v do not have color c
        for nb in adj[v]:
            if nb in assignment and assignment[nb] == c:
                return False
        return True

    def backtrack(idx: int) -> bool:
        if idx == len(vertices):
            return True
        v = vertices[idx]
        for c in colors:
            if valid(v, c):
                assignment[v] = c
                if backtrack(idx + 1):
                    return True
                # backtrack
                del assignment[v]
        return False

    # run solver
    success = backtrack(0)
    if not success:
        raise ValueError("No valid coloring found with 3 colors")
    return assignment

