    # brute-force search over all assignments of 3 colors to 6 vertices
    for prod in itertools.product(colors, repeat=6):
        assign: Dict[int, str] = {i + 1: prod[i] for i in range(6)}
        valid = True
        for (u, v) in edges:
            if assign[u] == assign[v]:
                valid = False
                break
        if valid:
