def solution() -> dict:
    from typing import Dict

    # Graph definition: undirected edges
    edges = {(1, 3), (1, 5), (1, 6), (2, 5), (4, 5), (4, 6), (5, 6)}
    # make edges bidirectional for easy checking
    edges = edges.union({(b, a) for (a, b) in edges})

    vertices = [1, 2, 3, 4, 5, 6]
    colors = ['A', 'B', 'C']

    assignment: Dict[int, str] = {}

    def valid(v: int, col: str) -> bool:
        # check neighbors already assigned
        for u in vertices:
            if (u, v) in edges and u in assignment and assignment[u] == col:
                return False
        return True

    def backtrack(i: int = 0) -> bool:
        if i == len(vertices):
            return True
        v = vertices[i]
        for col in colors:
            if valid(v, col):
                assignment[v] = col
                if backtrack(i + 1):
                    return True
                del assignment[v]
        return False

    backtrack()
    # Return a mapping from vertex to color (strings 'A','B','C')
    return {v: assignment[v] for v in vertices}

