def solution() -> dict:

    Find a 3-coloring of the given graph with vertices 1..10 using colors 'A','B','C'.
    Returns: Dict[int, str]

    from typing import Dict, List, Set, Tuple

    edges: List[Tuple[int, int]] = [
        (1,4),(1,7),(1,9),(1,10),
        (2,5),(2,10),
        (3,5),(3,9),(3,10),
        (4,6),
        (5,8),(5,10),
        (6,9),
        (8,9)
    ]
    # build adjacency
    adj: Dict[int, Set[int]] = {i:set() for i in range(1,11)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = ['A','B','C']
    assignment: Dict[int,str] = {}

    # simple backtracking over vertices 1..10
    def backtrack(node: int) -> bool:
        if node > 10:
            return True
        for c in colors:
            # check neighbors already assigned
            conflict = False
            for nb in adj[node]:
                if nb in assignment and assignment[nb] == c:
                    conflict = True
                    break
            if conflict:
                continue
            assignment[node] = c
            if backtrack(node+1):
                return True
            del assignment[node]
        return False

    if not backtrack(1):
        raise ValueError('No 3-coloring found')
    # return a mapping for vertices 1..10
    return {i: assignment[i] for i in range(1,11)}

