def solution() -> dict:
    from typing import Dict, List

    # Graph definition (undirected)
    edges = [
        (2, 3),
        (3, 6),
        (3, 8),
        (4, 5),
        (4, 7),
        (5, 7),
        (5, 9),
        (6, 8),
        (7, 8),
        (9, 10),
    ]

    # Build adjacency list for vertices 1..10
    adj = {i: set() for i in range(1, 11)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = ['A', 'B', 'C']
    assignment: Dict[int, str] = {}
    vertices: List[int] = list(range(1, 11))

    def valid(vertex: int, color: str) -> bool:
        for nei in adj[vertex]:
            if nei in assignment and assignment[nei] == color:
                return False
        return True

    def backtrack(index: int) -> bool:
        if index == len(vertices):
            return True
        v = vertices[index]
        for c in colors:
            if valid(v, c):
                assignment[v] = c
                if backtrack(index + 1):
                    return True
                # backtrack
                del assignment[v]
        return False

    success = backtrack(0)
    if not success:
        raise ValueError("No 3-coloring found")
    # Ensure return type is Dict[int, str]
    return {int(k): str(v) for k, v in assignment.items()}

